<script lang="ts">
 import {onMount,untrack} from 'svelte';import {zoned} from './logic';import CopyButton from '../../components/CopyButton.svelte';import type {ToolState} from '../../types';
 let {state:data=$bindable()}=$props<{state:ToolState}>();untrack(()=>{data.zone??='Asia/Tokyo';data.zones??=['Asia/Tokyo','UTC','America/New_York'];data.mode??='digital';data.error??='';});let now=$state(Date.now());let current=$derived(zoned(now,data.zones[0]||'UTC'));
 onMount(()=>{const interval=setInterval(()=>now=Date.now(),250);return ()=>clearInterval(interval);});
 function add(){try{zoned(now,data.zone);if(data.zones.length>=12)throw new Error('最大12地域です。');if(!data.zones.includes(data.zone))data.zones=[...data.zones,data.zone];data.error='';}catch(e){data.error=`有効なIANAタイムゾーンを入力してください。${(e as Error).message}`;}}
 const two=(value:number)=>String(value).padStart(2,'0');
</script>
<div class="form-grid"><label>表示形式<select bind:value={data.mode}><option value="digital">デジタル</option><option value="analog">アナログ＋デジタル</option></select></label><label>追加するタイムゾーン<input bind:value={data.zone} maxlength="100" list="timezones" placeholder="Asia/Tokyo"/></label></div><datalist id="timezones">{#each ['Asia/Tokyo','UTC','America/New_York','Europe/London','Europe/Paris','Asia/Shanghai','Asia/Kolkata','Australia/Sydney'] as zone}<option value={zone}></option>{/each}</datalist>
<div class="action-row"><button class="primary" onclick={add}>世界時計を追加</button><button onclick={()=>{data.zones=['Asia/Tokyo','UTC','America/New_York'];data.error='';}}>リセット</button></div>
{#if data.error}<p role="alert" class="error">{data.error}</p>{/if}
{#if data.mode==='analog'}<div class="analog-wrap"><svg class="analog-clock" viewBox="0 0 200 200" role="img" aria-label={`${data.zones[0]} ${current.hour}時${current.minute}分${current.second}秒`}><circle cx="100" cy="100" r="93" fill="none" stroke="currentColor"/>{#each Array(12) as _,i}<line x1="100" y1="16" x2="100" y2="24" stroke="currentColor" transform={`rotate(${i*30} 100 100)`}/>{/each}<line x1="100" y1="105" x2="100" y2="53" stroke="currentColor" stroke-width="5" transform={`rotate(${current.hour*30+current.minute*.5} 100 100)`}/><line x1="100" y1="110" x2="100" y2="28" stroke="currentColor" stroke-width="3" transform={`rotate(${current.minute*6+current.second*.1} 100 100)`}/><line x1="100" y1="115" x2="100" y2="23" stroke="var(--accent)" stroke-width="1" transform={`rotate(${current.second*6} 100 100)`}/><circle cx="100" cy="100" r="4" fill="var(--accent)"/></svg><p class="tool-note">{data.zones[0]} / 最初の地域を表示</p></div>{/if}
<div class="world-clocks">{#each data.zones as zone}{@const time=zoned(now,zone)}<section class="world-clock"><div><h2>{zone}</h2><p>{time.date}</p></div><output>{two(time.hour)}:{two(time.minute)}:{two(time.second)}</output><div class="inline-actions"><CopyButton text={`${zone} ${time.date} ${two(time.hour)}:${two(time.minute)}:${two(time.second)}`}/><button disabled={data.zones.length===1} onclick={()=>data.zones=data.zones.filter((z:string)=>z!==zone)} aria-label={`${zone}を削除`}>削除</button></div></section>{/each}</div><p class="tool-note">端末の時計とブラウザ内のIANAタイムゾーンデータを使用します。時刻サーバーとは同期しません。夏時間はブラウザのタイムゾーン規則に従います。</p>
